%[text] %[text:anchor:T_D48C173C] # High Voltage Battery - Simulation Case
%[text] %[text:anchor:H_1B376934] ## Random current
model_name = "HarnessModel_BatteryHV";
load_system(model_name)

BatteryHV_Basic_params

set_param(model_name + "/High Voltage Battery", ReferencedSubsystem = "BatteryHV_Basic_refsub");

set_param(model_name + "/Inputs", ReferencedSubsystem = "Inputs_BatteryHV_Random_refsub");
%%
%[text] Test conditions
signal_design_matrix = bevutil1.SignalUtil.generateSignalDesignMatrixFromTraceProperties(...
  RandomSeed = 12, ...
  FInitialValue = 0, ...
  XInitialFlatLength = 5, ...
  XInitialTransitionLength = 5, ...
  NumTransitions = 20, ...
  TransitionXRange = [10 30], ...
  FlatXRange = [120 240], ...
  FRange = [-10 50], ...
  XFinalTransitionLength = 30, ...
  XFinalFlatLength = 100, ...
  FFinalValue = 0 );

data_table = bevutil1.SignalUtil.getVectorsFromSignalDesignMatrix(signal_design_matrix);

t = data_table.X;
f = data_table.F;

fig = figure; %[output:033f7327]
fig.Position(3:4) = [900 300];  % width height %[output:033f7327]
bevutil1.SignalUtil.plotLookupTable1D(t, f, InterpolationInterval=0.5, ParentAxes=axes(fig)) %[output:033f7327]
%%
set_param(model_name + "/Inputs/Load current", "Table", bevutil1.CodeUtil.stringify(f))
set_param(model_name + "/Inputs/Load current", "BreakpointsForDimension1", bevutil1.CodeUtil.stringify(t))
%[text] Initial conditions
initial.hvBattery_SOC_pct = 50;
initial.hvBattery_SOC_normalized = initial.hvBattery_SOC_pct / 100;

tmp_batt_charge = HighVoltageBatteryTool1.getAmpereHourRating( ...
  Capacity = simscape.Value(batteryHV.nominalCapacity_kWh, "kWh"), ...
  Voltage = simscape.Value(batteryHV.nominalVoltage_V, "V"), ...
  StateOfCharge = initial.hvBattery_SOC_normalized );

initial.hvBattery_Charge_Ahr = value(tmp_batt_charge, "Ah");
disp(initial) %[output:786bdff4]
%[text] Simulation
sim_in = Simulink.SimulationInput(model_name);
sim_in = setModelParameter(sim_in, StopTime = string(t(end)));

sim_out = sim(sim_in);

logged_signals = extractTimetable(sim_out.logsout);

BatteryHV_plotResults(Timetable = logged_signals); %[output:874e3efa]
